WpfGraphicsSettings.Code:
var u1 = u;
var v1 = v;

var b = 3.5;

//var a = 1.0;
var c = 189.7272;
var e1 = 6.87519;
var p4e = Math.PI / (4 * e1);
var p2e = Math.PI / (2 * e1);

Complex i = Complex.ImaginaryOne;
Complex w = new Complex(u1, v1);
var wh = w - 0.5;
var wi = w - 0.5 * i;

var Zw = cmath53.WeierstrassZeta(c, 0, w);
var Zwh = cmath53.WeierstrassZeta(c, 0, wh);
var Zwi = cmath53.WeierstrassZeta(c, 0, wi);
var Pw = cmath53.WeierstrassP(c, 0, w);

var x = (Math.PI * (u1 + p4e) - Zw + p2e * (Zwh - Zwi)).Real;
var z = (Math.PI * (v1 + p4e) - i * Zw - i * p2e * (Zwh - Zwi)).Real;
var y = Math.Sqrt(Math.PI / 2) * Math.Log(Complex.Abs((Pw - e1) / (Pw + e1)));

if (x > b) x = b;
if (x < -b) x = -b;
if (y > b) y = b;
if (y < -b) y = -b;
if (z > b) z = b;
if (z < -b) z = -b;
